  (v_mod, 'MKY-047', 'Atendimento a não-usuário — especialista bloqueado, mesmo sem acesso ao sistema, encontra canal e pede revisão', 'feliz', 'media', 'aprovado', 'e2e', 'RN-032, RN-033; seção 24.1; LGPD art. 18 e 20',
